const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaExclamationTriangle, FaUsers, FaBrain, FaPills, FaPray, FaComments, FaHeartbeat, FaShieldAlt, FaSearch, FaChartBar } = require("react-icons/fa");
const { MdOutlineHealthAndSafety, MdWarning } = require("react-icons/md");

// ─── Color palette ───────────────────────────────────────────────────────────
const C = {
  darkBg:    "0F2240",  // deep navy (title/closing slides)
  midBg:     "1A3A5C",  // mid navy
  lightBg:   "F5F8FC",  // off-white content slides
  accent:    "0891B2",  // teal accent
  accent2:   "14B8A6",  // seafoam secondary
  depBlue:   "1E5FAD",  // depression bar
  anxTeal:   "0891B2",  // anxiety bar
  schiPurp:  "7C3AED",  // schizophrenia bar
  bipOrange: "D97706",  // bipolar bar
  eatRose:   "DB2777",  // eating disorders bar
  white:     "FFFFFF",
  darkText:  "1E293B",
  mutedText: "64748B",
  lightCard: "FFFFFF",
  cardBorder:"E2E8F0",
};

async function iconToBase64(IconComponent, color = "#FFFFFF", size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "The Global Burden of Mental Illness";
  pres.author = "Public Health Analytics";

  // Pre-render icons
  const iconBrain    = await iconToBase64(FaBrain,       "#0891B2", 256);
  const iconPills    = await iconToBase64(FaPills,       "#0891B2", 256);
  const iconPray     = await iconToBase64(FaPray,        "#7C3AED", 256);
  const iconComments = await iconToBase64(FaComments,    "#14B8A6", 256);
  const iconWarn     = await iconToBase64(FaExclamationTriangle, "#D97706", 256);
  const iconHeart    = await iconToBase64(FaHeartbeat,   "#DB2777", 256);
  const iconShield   = await iconToBase64(FaShieldAlt,   "#0891B2", 256);
  const iconSearch   = await iconToBase64(FaSearch,      "#64748B", 256);
  const iconChart    = await iconToBase64(FaChartBar,    "#1E5FAD", 256);
  const iconUsers    = await iconToBase64(FaUsers,       "#FFFFFF", 256);

  // ═══════════════════════════════════════════════════════════════════════════
  // SLIDE 1 — Title
  // ═══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.darkBg };

    // Top accent bar
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.accent }, line: { color: C.accent } });

    // Left colored stripe
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0.08, w: 0.35, h: 5.545, fill: { color: C.accent }, line: { color: C.accent } });

    // Brain icon top-right circle
    s.addShape(pres.shapes.OVAL, { x: 8.1, y: 0.5, w: 1.4, h: 1.4, fill: { color: C.midBg }, line: { color: C.accent, pt: 2 } });
    s.addImage({ data: iconBrain, x: 8.38, y: 0.78, w: 0.84, h: 0.84 });

    // Title
    s.addText("The Global Burden\nof Mental Illness", {
      x: 0.65, y: 0.9, w: 7.2, h: 1.7,
      fontSize: 36, bold: true, color: C.white,
      fontFace: "Calibri", align: "left", margin: 0
    });

    // Subtitle
    s.addText("Prevalence, Impact, and the Treatment Gap", {
      x: 0.65, y: 2.65, w: 7.5, h: 0.5,
      fontSize: 18, color: C.accent2, bold: false,
      fontFace: "Calibri", align: "left", margin: 0
    });

    // Divider
    s.addShape(pres.shapes.RECTANGLE, { x: 0.65, y: 3.25, w: 5.5, h: 0.04, fill: { color: C.accent }, line: { color: C.accent } });

    // Meta line
    s.addText("Global Data • 2023  |  Source: Our World in Data / IHME, Global Burden of Disease", {
      x: 0.65, y: 3.45, w: 8.7, h: 0.35,
      fontSize: 11, color: "8BA8C8", fontFace: "Calibri", align: "left", margin: 0
    });

    // Audience
    s.addText("For: Public Health Policy Analysts & Mental Health Program Planners", {
      x: 0.65, y: 3.9, w: 8.7, h: 0.35,
      fontSize: 11, color: "8BA8C8", fontFace: "Calibri", align: "left", italic: true, margin: 0
    });

    // Bottom bar
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.425, w: 10, h: 0.2, fill: { color: C.midBg }, line: { color: C.midBg } });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SLIDE 2 — Mental Health Scale / Prevalence callouts
  // ═══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    // Header band
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg }, line: { color: C.darkBg } });
    s.addText("Hundreds of Millions Affected", {
      x: 0.4, y: 0.08, w: 9.2, h: 0.55,
      fontSize: 22, bold: true, color: C.white, fontFace: "Calibri", align: "left", margin: 0
    });

    // Subtitle
    s.addText("1 in 3 Women and 1 in 5 Men Will Experience Major Depression in Their Lifetime", {
      x: 0.4, y: 0.92, w: 9.2, h: 0.4,
      fontSize: 13, color: C.accent, fontFace: "Calibri", align: "left", bold: true, margin: 0
    });

    // ── Big callout cards ────────────────────────────────────────────────────
    // Card: Women
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: 1.45, w: 4.35, h: 2.2,
      fill: { color: C.darkBg }, line: { color: C.accent, pt: 2 }
    });
    s.addText("1 in 3", {
      x: 0.4, y: 1.5, w: 4.35, h: 1.1,
      fontSize: 64, bold: true, color: C.accent2,
      fontFace: "Calibri", align: "center", margin: 0
    });
    s.addText("WOMEN", {
      x: 0.4, y: 2.55, w: 4.35, h: 0.35,
      fontSize: 16, bold: true, color: C.white,
      fontFace: "Calibri", align: "center", margin: 0, charSpacing: 4
    });
    s.addText("will experience major depression\nin their lifetime", {
      x: 0.4, y: 2.9, w: 4.35, h: 0.5,
      fontSize: 11, color: "8BA8C8",
      fontFace: "Calibri", align: "center", margin: 0
    });

    // Card: Men
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.25, y: 1.45, w: 4.35, h: 2.2,
      fill: { color: C.darkBg }, line: { color: C.accent, pt: 2 }
    });
    s.addText("1 in 5", {
      x: 5.25, y: 1.5, w: 4.35, h: 1.1,
      fontSize: 64, bold: true, color: "F59E0B",
      fontFace: "Calibri", align: "center", margin: 0
    });
    s.addText("MEN", {
      x: 5.25, y: 2.55, w: 4.35, h: 0.35,
      fontSize: 16, bold: true, color: C.white,
      fontFace: "Calibri", align: "center", margin: 0, charSpacing: 4
    });
    s.addText("will experience major depression\nin their lifetime", {
      x: 5.25, y: 2.9, w: 4.35, h: 0.5,
      fontSize: 11, color: "8BA8C8",
      fontFace: "Calibri", align: "center", margin: 0
    });

    // Context text
    s.addShape(pres.shapes.RECTANGLE, { x: 0.4, y: 3.85, w: 9.2, h: 1.35, fill: { color: "EBF4FA" }, line: { color: C.cardBorder } });
    s.addText([
      { text: "Beyond depression, ", options: { color: C.darkText } },
      { text: "hundreds of millions", options: { color: C.accent, bold: true } },
      { text: " of people suffer from mental health conditions each year. Conditions span a spectrum — from common high-prevalence disorders (depression, anxiety) to less prevalent but severely disabling conditions (schizophrenia, bipolar disorder). Mental illnesses are ", options: { color: C.darkText } },
      { text: "treatable", options: { color: C.accent, bold: true } },
      { text: ", yet treatment often remains lacking or of poor quality.", options: { color: C.darkText } }
    ], {
      x: 0.65, y: 3.97, w: 8.7, h: 1.05,
      fontSize: 12, fontFace: "Calibri", align: "left", margin: 0
    });

    // Source
    s.addText("Source: Our World in Data / IHME, Global Burden of Disease (2023)", {
      x: 0.4, y: 5.32, w: 9.2, h: 0.22,
      fontSize: 9, color: C.mutedText, fontFace: "Calibri", align: "left", italic: true, margin: 0
    });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SLIDE 3 — Burden by Category (horizontal bar chart)
  // ═══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg }, line: { color: C.darkBg } });
    s.addText("Depression & Anxiety Dominate Global Mental Health Burden", {
      x: 0.4, y: 0.1, w: 9.2, h: 0.55,
      fontSize: 20, bold: true, color: C.white, fontFace: "Calibri", align: "left", margin: 0
    });

    s.addText("DALYs per 100,000 people, World, 2023", {
      x: 0.4, y: 0.88, w: 9.2, h: 0.3,
      fontSize: 11, color: C.mutedText, fontFace: "Calibri", italic: true, align: "left", margin: 0
    });

    // Draw horizontal bar chart manually for better styling
    const bars = [
      { label: "Depressive Disorders",  value: 694.6, color: C.depBlue  },
      { label: "Anxiety Disorders",     value: 686.5, color: C.anxTeal  },
      { label: "Schizophrenia",         value: 210.2, color: C.schiPurp },
      { label: "Bipolar Disorder",      value:  94.6, color: C.bipOrange},
      { label: "Eating Disorders",      value:  47.5, color: C.eatRose  },
    ];
    const maxVal = 750;
    const barAreaW = 5.8;
    const startX = 2.7;
    const startY = 1.33;
    const rowH = 0.62;
    const barH = 0.34;
    const gap = rowH - barH;

    bars.forEach((b, i) => {
      const y = startY + i * rowH;
      const barW = (b.value / maxVal) * barAreaW;

      // Row bg
      s.addShape(pres.shapes.RECTANGLE, {
        x: startX, y: y - 0.04, w: barAreaW, h: rowH - 0.02,
        fill: { color: i % 2 === 0 ? "EEF4FB" : "F8FAFC" },
        line: { color: "E2E8F0", pt: 0.5 }
      });

      // Bar
      s.addShape(pres.shapes.RECTANGLE, {
        x: startX, y: y + gap / 2, w: barW, h: barH,
        fill: { color: b.color }, line: { color: b.color }
      });

      // Label (left)
      s.addText(b.label, {
        x: 0.35, y: y + gap / 2, w: 2.25, h: barH,
        fontSize: 11, color: C.darkText, fontFace: "Calibri",
        align: "right", valign: "middle", margin: 0
      });

      // Value label (right of bar)
      s.addText(b.value.toFixed(1), {
        x: startX + barW + 0.1, y: y + gap / 2, w: 0.8, h: barH,
        fontSize: 11, bold: true, color: b.color, fontFace: "Calibri",
        align: "left", valign: "middle", margin: 0
      });
    });

    // X-axis label
    s.addText("DALYs per 100,000 population", {
      x: startX, y: startY + bars.length * rowH + 0.1, w: barAreaW, h: 0.25,
      fontSize: 10, color: C.mutedText, fontFace: "Calibri", align: "center", margin: 0
    });

    // Key insight box
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.35, y: 4.7, w: 9.3, h: 0.65,
      fill: { color: "E0F2FE" }, line: { color: C.accent, pt: 1 }
    });
    s.addText([
      { text: "Key Insight: ", options: { bold: true, color: C.accent } },
      { text: "Depression and anxiety together account for ~80% of the total mental health disease burden across these five categories.", options: { color: C.darkText } }
    ], {
      x: 0.55, y: 4.76, w: 9.0, h: 0.52,
      fontSize: 12, fontFace: "Calibri", align: "left", margin: 0
    });

    s.addText("Source: IHME, Global Burden of Disease (2023) via Our World in Data", {
      x: 0.4, y: 5.42, w: 9.2, h: 0.18,
      fontSize: 9, color: C.mutedText, fontFace: "Calibri", italic: true, align: "left", margin: 0
    });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SLIDE 4 — Depression vs Anxiety Parity (side-by-side paired bars)
  // ═══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

