      align: "center", charSpacing: 2, margin: 0
    });
    s.addText("694.6", {
      x: 0.4, y: 1.88, w: 4.3, h: 1.3,
      fontSize: 72, bold: true, color: C.white, fontFace: "Calibri",
      align: "center", margin: 0
    });
    s.addText("DALYs per 100,000", {
      x: 0.4, y: 3.15, w: 4.3, h: 0.35,
      fontSize: 12, color: "A8CBF0", fontFace: "Calibri",
      align: "center", margin: 0
    });
    s.addText("World, 2023", {
      x: 0.4, y: 3.5, w: 4.3, h: 0.3,
