      fontSize: 12, color: "A8E6E0", fontFace: "Calibri",
      align: "center", margin: 0
    });
    s.addText("World, 2023", {
      x: 5.3, y: 3.5, w: 4.3, h: 0.3,
      fontSize: 10, color: "A8E6E0", fontFace: "Calibri",
      align: "center", italic: true, margin: 0
    });

    // Diff callout
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: 4.38, w: 9.2, h: 0.75,
      fill: { color: "E0F2FE" }, line: { color: C.accent, pt: 1 }
    });
    s.addText([
      { text: "Difference of only 8.1 DALYs per 100,000 — ", options: { bold: true, color: C.accent } },
