        x: cx + 0.18, y: cy + 0.3, w: 0.65, h: 0.65,
        fill: { color: b.border }, line: { color: b.border }
      });
      s.addImage({ data: b.icon, x: cx + 0.29, y: cy + 0.41, w: 0.42, h: 0.42 });
      s.addText(b.title, {
        x: cx + 0.95, y: cy + 0.28, w: 3.45, h: 0.35,
        fontSize: 14, bold: true, color: C.darkText, fontFace: "Calibri", align: "left", margin: 0
      });
      s.addText(b.text, {
        x: cx + 0.18, y: cy + 0.78, w: 4.2, h: 0.85,
        fontSize: 10.5, color: C.darkText, fontFace: "Calibri", align: "left", margin: 0
      });
    });

    // Bottom banner
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.18, w: 10, h: 0.445, fill: { color: C.darkBg }, line: { color: C.darkBg } });
    s.addText("Good data is essential — to understand these conditions, how many people are affected, and how they can be treated effectively.", {
      x: 0.4, y: 5.22, w: 9.2, h: 0.35,
      fontSize: 10.5, color: C.accent2, fontFace: "Calibri", align: "left", italic: true, margin: 0
    });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SLIDE 7 — Coping Strategies
  // ═══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg }, line: { color: C.darkBg } });
    s.addText("How People Cope: From Medication to Faith to Family Conversations", {
      x: 0.4, y: 0.1, w: 9.2, h: 0.62,
      fontSize: 20, bold: true, color: C.white, fontFace: "Calibri", align: "left", margin: 0
    });

    s.addText("Global survey data reveals wide variation in how people deal with anxiety or depression", {
      x: 0.4, y: 0.9, w: 9.2, h: 0.3,
      fontSize: 11, color: C.mutedText, fontFace: "Calibri", italic: true, align: "left", margin: 0
    });

    // 3 coping strategy cards
    const strategies = [
      {
        icon: iconPills,
        color: C.depBlue,
        title: "Prescribed Medication",
        text: "Common in higher-income settings where healthcare systems provide structured pharmacological treatment.",
        bg: "EFF6FF"
      },
      {
        icon: iconPray,
        color: C.schiPurp,
        title: "Religious & Spiritual Activities",
        text: "Prevalent across many regions worldwide, particularly in communities where faith plays a central role in wellbeing.",
        bg: "F5F3FF"
      },
      {
        icon: iconComments,
        color: C.anxTeal,
        title: "Talking to Friends or Family",
        text: "A widely reported coping mechanism globally — informal social support as a primary mental health resource.",
        bg: "F0FEFA"
      },
    ];

    strategies.forEach((st, i) => {
      const cx = 0.35 + i * 3.2;
      s.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: 1.32, w: 3.0, h: 3.5,
        fill: { color: st.bg }, line: { color: st.color, pt: 2 }
      });
      // Icon circle top
      s.addShape(pres.shapes.OVAL, {
        x: cx + 1.0, y: 1.48, w: 1.0, h: 1.0,
        fill: { color: st.color }, line: { color: st.color }
      });
      s.addImage({ data: st.icon, x: cx + 1.17, y: 1.65, w: 0.66, h: 0.66 });
      s.addText(st.title, {
        x: cx + 0.1, y: 2.6, w: 2.8, h: 0.55,
        fontSize: 13, bold: true, color: C.darkText, fontFace: "Calibri",
        align: "center", margin: 0
      });
      s.addText(st.text, {
        x: cx + 0.12, y: 3.22, w: 2.76, h: 1.45,
        fontSize: 10.5, color: C.darkText, fontFace: "Calibri", align: "left", margin: 0
      });
    });

    // Bottom note
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.97, w: 10, h: 0.655, fill: { color: "E0F2FE" }, line: { color: C.accent, pt: 1 } });
    s.addText([
      { text: "Policy implication: ", options: { bold: true, color: C.accent } },
      { text: "The diversity of coping strategies — shaped by cultural, economic, and healthcare system factors — means interventions must be ", options: { color: C.darkText } },
      { text: "culturally sensitive", options: { bold: true, color: C.darkText } },
      { text: " rather than one-size-fits-all.", options: { color: C.darkText } }
    ], {
      x: 0.5, y: 5.02, w: 9.1, h: 0.55,
      fontSize: 11, fontFace: "Calibri", align: "left", margin: 0
    });

    s.addText("Source: Global survey data via Our World in Data / IHME (2023)", {
      x: 0.4, y: 5.44, w: 9.2, h: 0.18,
      fontSize: 9, color: C.mutedText, fontFace: "Calibri", italic: true, align: "left", margin: 0
    });
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SLIDE 8 — Takeaways & Policy Implications (dark closing slide)
  // ═══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.darkBg };

    // Top accent
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.accent }, line: { color: C.accent } });

    s.addText("Key Takeaways & Policy Implications", {
      x: 0.4, y: 0.18, w: 9.2, h: 0.6,
      fontSize: 26, bold: true, color: C.white, fontFace: "Calibri", align: "left", margin: 0
    });
    s.addText("Prioritizing Depression, Anxiety, and Closing the Treatment Gap", {
      x: 0.4, y: 0.78, w: 9.2, h: 0.35,
      fontSize: 13, color: C.accent2, fontFace: "Calibri", align: "left", italic: true, margin: 0
    });

    const points = [
      { num: "01", color: C.depBlue,   text: "Depression & anxiety represent the overwhelming majority of mental health DALYs (~695 and ~687 per 100,000 respectively) — policy investment should match this scale." },
      { num: "02", color: C.schiPurp,  text: "Schizophrenia and bipolar carry disproportionately high individual burden (210.2 and 94.6 DALYs/100K) despite lower prevalence — specialized care must be maintained." },
      { num: "03", color: C.bipOrange, text: "Treatment exists but access and quality remain inadequate — particularly in low- and middle-income countries where infrastructure lags far behind need." },
      { num: "04", color: C.eatRose,   text: "Stigma suppresses help-seeking and accurate data collection, meaning the true burden is likely underestimated. Destigmatization is a prerequisite for progress." },
      { num: "05", color: C.accent2,   text: "Scale evidence-based interventions for common mental disorders (depression, anxiety) while protecting specialized care for severe conditions. Culturally sensitive delivery is essential." },
    ];

    points.forEach((p, i) => {
      const y = 1.25 + i * 0.81;
      s.addShape(pres.shapes.RECTANGLE, {
        x: 0.35, y, w: 0.52, h: 0.52,
        fill: { color: p.color }, line: { color: p.color }
      });
      s.addText(p.num, {
        x: 0.35, y, w: 0.52, h: 0.52,
        fontSize: 13, bold: true, color: C.white, fontFace: "Calibri",
        align: "center", valign: "middle", margin: 0
      });
      s.addText(p.text, {
        x: 1.0, y: y + 0.03, w: 8.6, h: 0.5,
        fontSize: 11, color: "D1E8F5", fontFace: "Calibri", align: "left", margin: 0
      });
    });

    // Bottom bar
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.38, w: 10, h: 0.245, fill: { color: C.midBg }, line: { color: C.midBg } });
    s.addText("Data: IHME, Global Burden of Disease (2023)  |  Our World in Data — Mental Health  |  Dattani, Rodés-Guirao, Ritchie & Roser (2023)", {
      x: 0.4, y: 5.41, w: 9.2, h: 0.2,
      fontSize: 9, color: "8BA8C8", fontFace: "Calibri", align: "left", italic: true, margin: 0
    });
  }

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Done: /app/output/final_deck.pptx");
}

main().catch(err => { console.error(err); process.exit(1); });

